        kept = [c.lower() for c in text if c.isalnum()]
        return kept == kept[::-1]

code.java:
class Solution {
    public boolean isMirror(String text) {
        StringBuilder kept = new StringBuilder();
        for (char c : text.toCharArray()) if (Character.isLetterOrDigit(c)) kept.append(Character.toLowerCase(c));
        String a = kept.toString();
        return a.equals(kept.reverse().toString());
    }
}

