#include <ctype.h>

bool isMirror(char* text) {
    int n = strlen(text), m = 0;
    char* kept = malloc(n + 1);
    for (int i = 0; i < n; i++) if (isalnum((unsigned char) text[i])) kept[m++] = tolower((unsigned char) text[i]);
    bool ok = true;
    for (int i = 0; i < m / 2 && ok; i++) if (kept[i] != kept[m - 1 - i]) ok = false;
    free(kept);
    return ok;
}

